/* Core concepts. `anim` → interactive animation in animations.js; `diagram` → flow diagram (diagram.js). */
window.SD = window.SD || {};
(function () {
  const n = (id, label, sub, type, x, y, desc, icon) => ({ id, label, sub, type, x, y, desc, icon });

  SD.conceptCategories = ["Fundamentals", "Networking & Traffic", "Caching", "Data & Storage", "Messaging & Streaming", "Distributed Systems", "Reliability & Resilience", "Architecture Patterns", "Security", "Observability", "Algorithms & Structures"];

  SD.concepts = [
    /* ------------------------- Fundamentals ------------------------- */
    { id: "scaling", cat: "Fundamentals", title: "Vertical vs Horizontal Scaling",
      summary: "Scale up (a bigger machine) or scale out (more machines). Most large systems scale out stateless tiers and scale data carefully.",
      points: ["Vertical (scale up): add CPU/RAM/disk. Simple, no code changes, but there's a hard ceiling, cost grows superlinearly, and it's a single point of failure.", "Horizontal (scale out): add more nodes behind a load balancer. Near-unlimited, fault tolerant, but needs stateless design and makes data harder to scale.", "Stateless app tiers scale out trivially. State (sessions, uploads) moves to shared stores such as Redis, a DB or S3.", "Data-tier scaling path: bigger box → read replicas → caching → functional partitioning (split by feature) → sharding."],
      use: ["Start vertical (it's cheap and simple); design stateless so you can go horizontal", "Autoscale app servers on CPU/QPS/queue depth"],
      pitfalls: ["Sticky sessions that tie users to servers", "Local disk state on app servers", "Scaling the app tier while the DB is the real bottleneck"] },
    { id: "latency-throughput", cat: "Fundamentals", title: "Latency, Throughput & Percentiles",
      summary: "Latency is how long one request takes; throughput is how many requests per second you handle. Always reason in percentiles.",
      points: ["Latency is measured as p50 / p95 / p99 / p999. Averages hide tail pain.", "Tail latency amplifies with fan-out: if a page calls 100 services each with p99 = 1 s, ~63% of page loads hit at least one slow call.", "Little's Law: concurrency = throughput × latency. At 1000 req/s × 200 ms you have 200 requests in flight.", "Throughput is limited by the bottleneck resource (CPU, I/O, locks, network, a downstream service)."],
      use: ["Set SLOs on p99, not averages", "Use hedged requests or timeouts to cut tail latency on fan-out"],
      pitfalls: ["Optimising the average", "Ignoring queueing: latency grows sharply as utilisation approaches 100%"] },
    { id: "availability", cat: "Fundamentals", title: "Availability, SLAs & the Nines",
      summary: "Availability = uptime / total time. Each extra nine is roughly 10× harder and more expensive.",
      points: ["99% ≈ 3.65 days down/year · 99.9% ≈ 8.8 h · 99.99% ≈ 52.6 min · 99.999% ≈ 5.3 min.", "Components in series multiply: 99.9% × 99.9% = 99.8%.", "Components in parallel (redundant): 1 − (1 − 0.999)² = 99.9999%.", "SLI = what you measure (success rate), SLO = your target (99.9%), SLA = contractual promise with penalties. Error budget = 1 − SLO."],
      use: ["Remove single points of failure with redundancy across AZs/regions", "Spend the error budget on shipping velocity; freeze when it's exhausted"],
      pitfalls: ["Promising five nines on a design with a single database", "Forgetting dependencies' availability (DNS, auth, third parties)"] },
    { id: "cap", cat: "Fundamentals", anim: "cap", title: "CAP Theorem & PACELC",
      summary: "During a network partition, a distributed system must choose between Consistency and Availability. PACELC adds: Else, choose between Latency and Consistency.",
      points: ["C: every read sees the most recent write (linearizability). A: every request to a non-failed node gets a (non-error) response. P: the system keeps working despite dropped messages between nodes.", "Partitions will happen, so the real choice is CP vs AP when a partition occurs.", "CP examples: Spanner, etcd/ZooKeeper, HBase, MongoDB (default). They refuse or block some requests during a partition.", "AP examples: Cassandra, DynamoDB (default), Riak, CouchDB. They answer, possibly with stale data, and reconcile later.", "PACELC: if Partition → A or C; Else (normal operation) → Latency or Consistency. DynamoDB/Cassandra are PA/EL; Spanner is PC/EC."],
      use: ["CP for money, inventory, locks and leader election", "AP for feeds, carts, likes and view counts, where availability beats freshness"],
      pitfalls: ["Saying a system is 'CA' (not meaningful for distributed systems)", "Treating CAP as a global switch; choices can be per operation"] },
    { id: "consistency-models", cat: "Fundamentals", title: "Consistency Models",
      summary: "A spectrum of guarantees about what reads can return, from linearizable to eventual.",
      points: ["Linearizable (strong): operations appear instantaneous and in real-time order. Like a single copy.", "Sequential: all nodes see operations in the same order (not necessarily real-time).", "Causal: causally related operations are seen in order by everyone (a reply is never seen before its question).", "Read-your-writes: you always see your own writes (route a user's reads to the primary for a few seconds after a write).", "Monotonic reads: you never see time go backwards (stick to one replica).", "Eventual: if writes stop, replicas converge eventually."],
      use: ["Strong for uniqueness constraints and balances", "Read-your-writes for user profile edits", "Eventual for counters and social feeds"],
      pitfalls: ["Reading from a lagging replica right after a write, then showing stale UI", "Paying for global strong consistency where eventual is fine"] },
    { id: "acid-base", cat: "Fundamentals", title: "ACID vs BASE",
      summary: "ACID guarantees transactional correctness; BASE trades it for availability and scale.",
      points: ["Atomicity: all or nothing. Consistency: invariants/constraints hold. Isolation: concurrent transactions don't interfere. Durability: committed means persisted (WAL + fsync).", "BASE: Basically Available, Soft state, Eventually consistent. Typical of NoSQL at scale.", "Modern NoSQL often offers limited ACID (DynamoDB transactions, MongoDB multi-document transactions)."],
      use: ["ACID for financial/booking/inventory", "BASE for high-scale, loss-tolerant, or naturally mergeable data"],
      pitfalls: ["Assuming ACID across microservices (it isn't; use sagas)"] },
    { id: "back-of-envelope", cat: "Fundamentals", title: "Back-of-the-Envelope Estimation",
      summary: "Quickly size QPS, storage, bandwidth and memory to justify design choices. See the Numbers page for the calculator.",
      points: ["QPS = DAU × actions per user per day ÷ 86,400 (≈ 10⁵). Peak ≈ 2–10× average.", "Storage = writes/day × object size × retention × replication factor.", "Bandwidth = QPS × response size.", "Cache (80/20 rule): cache ~20% of daily read volume.", "Round aggressively: 1 day ≈ 10⁵ s, 1 M req/day ≈ 12 req/s, 1 B req/day ≈ 12 K req/s."],
      use: ["Decide if one DB node suffices, whether to shard, how many servers"],
      pitfalls: ["False precision; interviewers want orders of magnitude"] },

    /* --------------------- Networking & Traffic --------------------- */
    { id: "load-balancing", cat: "Networking & Traffic", anim: "lb", title: "Load Balancing",
      summary: "Distributes requests across servers for scale and availability, and removes unhealthy instances via health checks.",
      points: ["L4 (transport): routes on IP/port, very fast, protocol-agnostic (NLB, HAProxy TCP mode).", "L7 (application): routes on HTTP path, headers or cookies; TLS termination, retries, canary (ALB, Nginx, Envoy).", "Algorithms: round robin, weighted round robin, least connections, least response time, IP/consistent hash (stickiness), random-of-two (power of two choices).", "Health checks remove failed instances; connection draining lets in-flight requests finish during deploys.", "The LB itself needs redundancy: active-passive pairs with a floating IP, or DNS/anycast across many LBs."],
      use: ["Least connections for long-lived or variable-cost requests", "Consistent hashing when a backend keeps per-key state or cache"],
      pitfalls: ["A single LB as a SPOF", "Sticky sessions causing uneven load and painful failover"] },
    { id: "dns", cat: "Networking & Traffic", title: "DNS Resolution",
      summary: "Translates names to IPs via a hierarchy of servers with caching at every level. It also acts as a global traffic router.",
      points: ["Resolution goes browser cache → OS → recursive resolver → root → TLD → authoritative.", "TTL controls caching. A low TTL gives faster failover but more queries.", "GeoDNS / latency-based routing sends users to the nearest region. Weighted records enable gradual migrations.", "Record types: A/AAAA (IP), CNAME (alias), MX (mail), TXT, NS, SRV."],
      use: ["Multi-region failover and geo-routing (Route 53, Cloudflare)"],
      pitfalls: ["Clients ignoring TTLs (e.g. JVM caching forever)", "DNS as the only failover mechanism when you need sub-minute RTO"],
      diagram: { nodes: [
        n("b", "Browser", "cache miss", "client", 80, 260, "Checks browser and OS caches first."),
        n("r", "Recursive Resolver", "ISP / 8.8.8.8", "service", 320, 260, "Does the legwork and caches answers for their TTL.", "dns"),
        n("root", "Root Server", ". (13 clusters)", "edge", 600, 80, "Knows where each TLD's servers are.", "dns"),
        n("tld", "TLD Server", ".com", "edge", 820, 260, "Knows the authoritative servers for every .com domain.", "dns"),
        n("auth", "Authoritative NS", "example.com", "edge", 600, 440, "Holds the actual records for the zone.", "dns")
      ], edges: [["b", "r"], ["r", "root"], ["r", "tld"], ["r", "auth"]], flows: [{ name: "Resolve example.com", steps: [
        ["b", "r", "A record for www.example.com?"],
        ["r", "root", "Where is .com?"],
        ["root", "r", "Ask a.gtld-servers.net"],
        ["r", "tld", "Where is example.com?"],
        ["tld", "r", "Ask ns1.example.com"],
        ["r", "auth", "A record for www.example.com?"],
        ["auth", "r", "93.184.216.34, TTL 300"],
        ["r", "b", "Answer (cached for 300 s at each layer)"]
      ]}]} },
    { id: "cdn", cat: "Networking & Traffic", anim: "cdn", title: "CDN (Content Delivery Network)",
      summary: "A global network of edge caches that serves content close to users, cutting latency and origin load.",
      points: ["Pull CDN: the edge fetches from the origin on first request, then caches (by TTL / Cache-Control). Simple.", "Push CDN: you upload content to the CDN proactively. Good for large, predictable assets.", "Cache static assets, media and even API responses (with short TTLs). Edge compute (Workers, Lambda@Edge) runs logic at the edge.", "An origin shield (mid-tier cache) collapses misses from many edges into one origin request.", "Invalidation: versioned filenames (app.3f9a.js) beat purges."],
      use: ["Images, video segments, JS/CSS, downloads", "DDoS absorption and TLS termination near users"],
      pitfalls: ["Caching personalised responses publicly", "Long TTLs without versioned URLs, so users see stale assets"] },
    { id: "proxy-gateway", cat: "Networking & Traffic", title: "Reverse Proxy & API Gateway",
      summary: "A reverse proxy sits in front of servers. An API gateway is a reverse proxy with API-management features.",
      points: ["Forward proxy: acts for clients (corporate egress). Reverse proxy: acts for servers (Nginx, Envoy).", "Reverse proxy features: TLS termination, compression, caching, request buffering, hiding internal topology.", "API gateway adds authentication, rate limiting, request routing to microservices, request/response transformation, API keys, analytics.", "BFF (Backend for Frontend): a gateway tailored per client type (mobile vs web)."],
      use: ["A single entry point for many microservices", "Centralised cross-cutting concerns"],
      pitfalls: ["Putting business logic in the gateway", "The gateway becoming a bottleneck or SPOF without redundancy"] },
    { id: "realtime", cat: "Networking & Traffic", anim: "realtime", title: "Polling vs Long Polling vs SSE vs WebSockets",
      summary: "Ways for a server to get fresh data to the client, trading simplicity against efficiency and latency.",
      points: ["Short polling: the client asks every N seconds. Simple, but mostly empty responses and up to N seconds of delay.", "Long polling: the server holds the request until data arrives or it times out, then the client immediately re-requests. Near real-time over plain HTTP.", "Server-Sent Events: one long-lived HTTP response streaming events server → client. Auto-reconnect, text only, one direction.", "WebSockets: an upgraded, full-duplex TCP connection. Lowest overhead for chatty bi-directional traffic, but stateful servers need sticky routing and a pub/sub backplane.", "WebTransport / HTTP/3 and gRPC streaming are modern alternatives."],
      use: ["Chat / multiplayer / collaborative editing → WebSockets", "Live scores, notifications, LLM token streams → SSE", "Infrequent updates → polling"],
      pitfalls: ["Forgetting that WS servers are stateful (scaling, deploys, reconnect storms)", "Not handling reconnects and missed messages (use sequence numbers)"] },
    { id: "api-styles", cat: "Networking & Traffic", title: "REST vs GraphQL vs gRPC",
      summary: "Choose the API style that fits the clients and the communication pattern.",
      points: ["REST: resources + HTTP verbs, cacheable, universal. Can over- or under-fetch.", "GraphQL: the client specifies exactly the fields it needs in one round trip. Great for varied frontends. Caching and N+1 resolvers are harder, and you need query-cost limits.", "gRPC: Protobuf over HTTP/2, strongly typed, fast, supports streaming. Ideal for internal service-to-service calls. Browser support needs a proxy.", "Also: WebSockets for real-time, webhooks for server-to-server callbacks, async messaging for decoupling."],
      use: ["Public APIs → REST", "Complex UIs aggregating many entities → GraphQL", "Internal microservices → gRPC"],
      pitfalls: ["Chatty REST calls over high-latency mobile links", "Unbounded GraphQL queries (enforce depth and complexity limits)"],
      table: [["", "REST", "GraphQL", "gRPC"], ["Transport", "HTTP/1.1+ JSON", "HTTP JSON", "HTTP/2 Protobuf"], ["Typing", "OpenAPI (optional)", "Schema (strong)", "Proto (strong)"], ["Caching", "Easy (HTTP)", "Hard", "Custom"], ["Streaming", "No (use SSE/WS)", "Subscriptions", "Bi-directional"], ["Best for", "Public APIs", "Flexible frontends", "Internal RPC"]] },

    /* ---------------------------- Caching --------------------------- */
    { id: "caching", cat: "Caching", anim: "cache", title: "Caching Strategies",
      summary: "Where and how you populate and update a cache determines freshness, latency and failure behaviour.",
      points: ["Cache-aside (lazy loading): the app reads the cache, and on a miss reads the DB and fills the cache. On write it updates the DB and invalidates the key. The most common pattern.", "Read-through: the cache itself loads from the DB on a miss (the app only talks to the cache).", "Write-through: writes go to the cache and the DB synchronously. The cache is always fresh, but writes are slower.", "Write-behind (write-back): write to the cache, acknowledge, and flush to the DB asynchronously in batches. Fast writes, but you risk data loss.", "Write-around: write to the DB only; the cache fills on later reads. Avoids polluting the cache with write-once data.", "Cache layers: client/browser → CDN → API gateway → application (in-process) → distributed cache (Redis) → DB buffer pool."],
      use: ["Cache-aside + TTL as the default", "Write-behind for high-rate counters where small loss is OK"],
      pitfalls: ["Updating the cache on write (races) instead of deleting it", "No TTL means data is stale forever if an invalidation is missed"] },
    { id: "eviction", cat: "Caching", title: "Cache Eviction Policies",
      summary: "When the cache is full, what gets thrown out?",
      points: ["LRU: evict the least recently used. The default for most workloads.", "LFU: evict the least frequently used. Better for stable popularity (Redis allkeys-lfu).", "FIFO: evict the oldest inserted. Simple, rarely optimal.", "TTL-based expiry: entries expire after a fixed time. Combine with LRU.", "W-TinyLFU (Caffeine): an admission filter + LRU. Excellent hit ratios.", "Random: surprisingly OK at large sizes, and cheap."],
      use: ["LRU for recency-heavy access (sessions, feeds)", "LFU for long-lived popular items (product pages)"],
      pitfalls: ["A cache too small for the working set means thrashing"] },
    { id: "cache-problems", cat: "Caching", title: "Stampede, Penetration, Avalanche & Hot Keys",
      summary: "The classic ways caches fail under load, and how to defend against each.",
      points: ["Cache stampede (thundering herd): a hot key expires and thousands of requests hit the DB at once. Fixes: request coalescing (single flight), a lock or lease on recompute, probabilistic early refresh, stale-while-revalidate.", "Cache penetration: requests for keys that don't exist always miss. Fixes: cache negative results (short TTL) and use a Bloom filter of valid keys.", "Cache avalanche: many keys expire together, or the cache cluster restarts. Fixes: jitter TTLs, warm caches, replicas, circuit breakers on the DB.", "Hot key: one key gets a huge share of traffic (a celebrity, a flash-sale item). Fixes: local in-process cache, replicate the key across shards (key#1..N), request coalescing."],
      use: ["Always jitter TTLs", "Single-flight for expensive recomputation"],
      pitfalls: ["Letting a cold cache after a deploy flatten the DB"] },

    /* ------------------------- Data & Storage ----------------------- */
    { id: "replication", cat: "Data & Storage", anim: "replication", title: "Replication",
      summary: "Keep copies of data on multiple nodes for availability, read scaling and durability.",
      points: ["Single-leader (primary/replica): all writes go to the leader and stream to followers. Simple, the most common setup (Postgres, MySQL).", "Multi-leader: several nodes accept writes (multi-region). Requires conflict resolution.", "Leaderless (Dynamo-style): write to W of N replicas, read from R. Tunable (Cassandra, DynamoDB).", "Synchronous: the leader waits for follower acks. No data loss on failover, but higher latency. Async: fast, but recent writes can be lost and replicas lag. Semi-sync: wait for one.", "Failover: detect the leader is dead → elect the most up-to-date follower → reconfigure clients. Beware split brain (two leaders): use fencing tokens and quorum."],
      use: ["Read replicas to scale read-heavy workloads", "Cross-AZ synchronous standby for HA"],
      pitfalls: ["Reading your own write from a lagging replica", "Split brain after a network partition"] },
    { id: "sharding", cat: "Data & Storage", anim: "sharding", title: "Sharding / Partitioning",
      summary: "Split data across nodes so each holds a subset, scaling storage and write throughput horizontally.",
      points: ["Range-based: shard by key ranges (A–F, G–M…). Range scans are efficient, but you risk hotspots (sequential keys, popular letters).", "Hash-based: shard = hash(key) mod N or consistent hashing. Even distribution, but range queries touch all shards.", "Directory-based: a lookup service maps key → shard. Flexible, but it's an extra hop and a potential SPOF.", "Geo / tenant-based: shard by region or customer. Good for data residency and isolation.", "Choosing the shard key: high cardinality, even access, and the most common queries should hit one shard.", "Costs: cross-shard joins and transactions, rebalancing, secondary indexes (local vs global)."],
      use: ["When data or write volume exceeds one node", "Multi-tenant SaaS (shard by tenant_id)"],
      pitfalls: ["A monotonically increasing shard key (timestamp) sends all writes to one shard", "Celebrity / hot partitions", "Sharding too early (a big Postgres goes very far)"] },
    { id: "consistent-hashing", cat: "Data & Storage", anim: "consistent-hashing", title: "Consistent Hashing",
      summary: "Map keys and nodes onto a ring so adding or removing a node only moves ~1/N of keys.",
      points: ["With hash(key) mod N, changing N remaps almost every key, which means a cache wipe or a massive migration.", "Consistent hashing places nodes on a hash ring; a key belongs to the first node clockwise.", "Virtual nodes: each physical node owns many points on the ring, which gives even load and lets weights follow capacity.", "Used in Dynamo, Cassandra, Riak, Memcached clients, CDNs, load balancers (Maglev), Discord.", "Alternatives: rendezvous (HRW) hashing, jump consistent hash."],
      use: ["Distributed caches and KV stores", "Sticky routing of users/keys to servers"],
      pitfalls: ["Too few virtual nodes means uneven load"] },
    { id: "indexing", cat: "Data & Storage", title: "Database Indexes",
      summary: "Auxiliary data structures that make reads fast at the cost of slower writes and extra storage.",
      points: ["B-tree / B+tree: the default; supports equality and range queries, O(log n).", "Hash index: O(1) equality only.", "Composite index (a, b): leftmost-prefix rule. It serves WHERE a=? and WHERE a=? AND b=?, but not b alone.", "Covering index: includes all queried columns, so the table is never touched (index-only scan).", "Specialised: GIN (JSONB, arrays, full-text), GiST/R-tree (geo), BRIN (huge naturally ordered tables), bitmap (low cardinality, OLAP).", "Secondary indexes in sharded systems are local (scatter-gather reads) or global (async, cross-shard writes)."],
      use: ["Index the columns in WHERE, JOIN and ORDER BY of hot queries; check with EXPLAIN"],
      pitfalls: ["Over-indexing write-heavy tables", "Functions on indexed columns (WHERE lower(email)=…) without an expression index"] },
    { id: "storage-engines", cat: "Data & Storage", anim: "lsm", title: "Storage Engines: B-Tree vs LSM-Tree",
      summary: "B-trees update pages in place (read-optimised); LSM-trees append and merge (write-optimised).",
      points: ["LSM write path: WAL append → in-memory memtable (sorted) → flush to immutable SSTable → background compaction merges files.", "LSM read path: memtable → SSTables newest to oldest. Bloom filters skip files that can't contain the key.", "Write amplification (B-tree page rewrites) vs read amplification (LSM checks many files) vs space amplification.", "LSM: Cassandra, RocksDB, LevelDB, ScyllaDB, HBase, Bigtable. B-tree: Postgres, MySQL/InnoDB, SQL Server."],
      use: ["Write-heavy ingestion → LSM", "Read-heavy with range queries and transactions → B-tree"],
      pitfalls: ["Compaction storms hurting latency", "Tombstone build-up from deletes in LSM stores"] },
    { id: "normalization", cat: "Data & Storage", title: "Normalisation vs Denormalisation",
      summary: "Normalise to avoid redundancy and anomalies; denormalise to make reads fast.",
      points: ["Normalised (3NF): each fact is stored once; joins reassemble. Consistent writes, flexible queries.", "Denormalised: duplicate data where it's read (embed the author's name in a post). Fast reads, but updates must fan out.", "NoSQL design is usually query-first denormalisation (one table per access pattern in Cassandra; single-table design in DynamoDB).", "Materialised views and CQRS read models are controlled denormalisation."],
      use: ["Normalise the system of record; denormalise read models and caches"],
      pitfalls: ["Denormalising without a plan to keep copies in sync"] },
    { id: "isolation-levels", cat: "Data & Storage", title: "Transaction Isolation Levels",
      summary: "How much concurrent transactions can see of each other, which trades correctness for concurrency.",
      points: ["Read uncommitted: dirty reads possible.", "Read committed: no dirty reads, but non-repeatable reads are possible. (Postgres default)", "Repeatable read / snapshot isolation: a consistent snapshot, but write skew is possible. (MySQL InnoDB default)", "Serializable: the result is equivalent to some serial order (2PL or SSI). Safest, but has more aborts and blocking.", "Anomalies: dirty read, non-repeatable read, phantom read, lost update, write skew (e.g. two doctors both go off call)."],
      use: ["SELECT … FOR UPDATE or serializable for check-then-act on money and bookings"],
      pitfalls: ["Assuming the default level prevents lost updates in read-modify-write code"],
      table: [["Level", "Dirty read", "Non-repeatable", "Phantom", "Write skew"], ["Read uncommitted", "✗ possible", "✗", "✗", "✗"], ["Read committed", "✓ prevented", "✗", "✗", "✗"], ["Repeatable read / SI", "✓", "✓", "✓/✗ (engine)", "✗"], ["Serializable", "✓", "✓", "✓", "✓"]] },
    { id: "quorum", cat: "Data & Storage", anim: "quorum", title: "Quorum Reads & Writes (N, W, R)",
      summary: "In leaderless replication, tune consistency by choosing how many replicas must ack writes (W) and answer reads (R).",
      points: ["N = replicas per key. W = write acks required. R = replicas consulted per read.", "If W + R > N, the read and write sets overlap, so a read sees at least one up-to-date replica.", "N=3, W=2, R=2 is the classic balance. W=1/R=N gives fast writes and slow reads; W=N/R=1 is the reverse.", "Versions are resolved with timestamps (LWW) or vector clocks; stale replicas are fixed by read repair and anti-entropy.", "Sloppy quorums + hinted handoff keep writes available during failures, but weaken the overlap guarantee."],
      use: ["Cassandra consistency levels (QUORUM, LOCAL_QUORUM), DynamoDB strongly consistent reads"],
      pitfalls: ["Believing quorum = linearizable (it isn't with sloppy quorums or LWW clock skew)"] },
    { id: "cdc-outbox", cat: "Data & Storage", title: "Change Data Capture & Transactional Outbox",
      summary: "Reliably propagate database changes to other systems (search, caches, analytics, other services) without dual writes.",
      points: ["Dual-write problem: writing to the DB and then publishing to Kafka can fail between the two, so the systems diverge.", "CDC: tail the DB's replication log (Postgres WAL, MySQL binlog) with Debezium and stream every change to Kafka.", "Outbox: in the same transaction as the business change, insert an event row into an outbox table. A relay (or CDC) publishes it. It's atomic by construction.", "Consumers must be idempotent (at-least-once delivery)."],
      use: ["Keeping Elasticsearch, caches and warehouses in sync", "Reliable domain events between microservices"],
      pitfalls: ["Publishing events before the transaction commits (phantom events)"],
      diagram: { nodes: [
        n("svc", "Order Service", "", "service", 90, 260, "Business logic."),
        n("db", "Postgres", "orders + outbox", "db", 280, 260, "One ACID transaction writes the order row and the outbox event row."),
        n("cdc", "CDC", "Debezium", "worker", 470, 260, "Tails the WAL / binlog, so no polling or dual writes."),
        n("k", "Kafka", "order-events", "queue", 660, 260, "A durable, replayable event log."),
        n("es", "Search Index", "Elasticsearch", "search", 870, 110, "Kept in sync automatically."),
        n("cache", "Cache Invalidator", "", "cache", 870, 260, "Deletes stale cache keys."),
        n("wh", "Warehouse", "Snowflake", "analytics", 870, 410, "Analytics copy.")
      ], edges: [["svc", "db"], ["db", "cdc"], ["cdc", "k"], ["k", "es"], ["k", "cache"], ["k", "wh"]], flows: [{ name: "Outbox via CDC", steps: [
        ["svc", "db", "BEGIN; INSERT order; INSERT outbox(OrderCreated); COMMIT"],
        ["db", "cdc", "The commit appears in the WAL"],
        ["cdc", "k", "Publish OrderCreated (at-least-once)"],
        ["k", "es", "Index the order for search"],
        ["k", "cache", "Invalidate order:{id}"],
        ["k", "wh", "Load into the warehouse"]
      ]}]} },

    /* --------------------- Messaging & Streaming -------------------- */
    { id: "queues-pubsub", cat: "Messaging & Streaming", anim: "queue", title: "Message Queues vs Pub/Sub vs Logs",
      summary: "Asynchronous messaging decouples producers and consumers, absorbs spikes and enables fan-out.",
      points: ["Queue (point-to-point): each message is processed by one consumer among many competing ones. Work distribution (SQS, RabbitMQ).", "Pub/Sub: each message is delivered to every subscriber. Fan-out of events (SNS, Google Pub/Sub, Redis Pub/Sub).", "Log (Kafka, Kinesis, Pulsar): an append-only partitioned log; consumers track offsets. Replayable, ordered per partition, and consumer groups give both queue and pub/sub semantics.", "Benefits: decoupling, buffering and load levelling, retries, async processing, independent scaling.", "Watch the backlog (consumer lag) and apply backpressure."],
      use: ["Queue: jobs, emails, image processing", "Pub/Sub: domain events to many services", "Kafka: event streaming, CDC, analytics pipelines, event sourcing"],
      pitfalls: ["No DLQ for poison messages", "Assuming global ordering (Kafka orders only within a partition)"],
      table: [["", "SQS / RabbitMQ", "Kafka"], ["Model", "Queue (delete on ack)", "Log (retain, offsets)"], ["Replay", "No", "Yes"], ["Ordering", "FIFO queues (limited)", "Per partition"], ["Throughput", "High", "Very high (millions/s)"], ["Routing", "Rich (RabbitMQ exchanges)", "Topic/partition"]] },
    { id: "delivery-semantics", cat: "Messaging & Streaming", title: "Delivery Semantics & Idempotency",
      summary: "At-most-once, at-least-once, exactly-once: what's achievable, and how to get exactly-once effects.",
      points: ["At-most-once: fire and forget; messages may be lost. Acceptable for metrics sampling.", "At-least-once: retry until acked; duplicates are possible. The practical default.", "Exactly-once delivery is impossible in general across networks, but exactly-once processing is achievable: at-least-once + idempotent consumers, or transactional read-process-write (Kafka transactions, Flink checkpoints).", "Idempotency techniques: unique message/request IDs stored in a dedup table, conditional writes (version checks), naturally idempotent operations (SET x=5, not x+=1)."],
      use: ["Payments, orders and notifications all need idempotency keys"],
      pitfalls: ["Non-idempotent consumers + retries = double charges or duplicate emails"] },
    { id: "event-driven", cat: "Messaging & Streaming", title: "Event Sourcing & CQRS",
      summary: "Store state as a sequence of events; separate the write model from read models optimised for queries.",
      points: ["Event sourcing: the source of truth is an append-only log of events (Deposited $50, Withdrew $20). Current state = fold(events). You get a full audit trail and time travel.", "CQRS: commands go to a write model; events update denormalised read models (projections) tuned per query.", "Snapshots bound replay time. Event schemas must be versioned.", "Often combined, but either works alone."],
      use: ["Ledgers, audit-heavy domains, collaborative apps", "Very different read and write shapes/scales"],
      pitfalls: ["Complexity for simple CRUD apps", "Read models are eventually consistent"],
      diagram: { nodes: [
        n("u", "Client", "", "client", 80, 260, "Sends commands and queries."),
        n("cmd", "Command API", "validate", "service", 280, 130, "Validates commands against the current state and emits events."),
        n("es", "Event Store", "append-only", "db", 500, 130, "The immutable sequence of events is the source of truth."),
        n("bus", "Event Bus", "Kafka", "queue", 700, 130, "Distributes new events."),
        n("proj", "Projectors", "", "worker", 700, 390, "Build read models from events."),
        n("read", "Read Models", "SQL / ES / Redis", "db", 500, 390, "Denormalised views per query."),
        n("q", "Query API", "", "service", 280, 390, "Serves reads fast from the read models.")
      ], edges: [["u", "cmd"], ["cmd", "es"], ["es", "bus"], ["bus", "proj"], ["proj", "read"], ["q", "read"], ["u", "q"]], flows: [{ name: "Command → projection → query", steps: [
        ["u", "cmd", "Withdraw $20 from account 7"],
        ["cmd", "es", "Load events → balance $50 → OK → append Withdrew($20)"],
        ["es", "bus", "Publish the new event"],
        ["bus", "proj", "Projector consumes it"],
        ["proj", "read", "Update balance view → $30"],
        ["u", "q", "GET balance"],
        ["q", "read", "Read the precomputed view (may lag by milliseconds)"]
      ]}]} },
    { id: "batch-stream", cat: "Messaging & Streaming", title: "Batch vs Stream Processing",
      summary: "Process bounded datasets periodically, or unbounded streams continuously.",
      points: ["Batch (MapReduce, Spark, dbt): high throughput, simple correctness, hours of latency.", "Stream (Flink, Kafka Streams, Spark Structured Streaming): seconds of latency; windows, watermarks and state.", "Windows: tumbling (fixed, non-overlapping), sliding / hopping (overlapping), session (gap-based).", "Event time vs processing time; watermarks decide when a window is complete; late data handling.", "Lambda architecture: batch + speed layers. Kappa: stream only, reprocess by replaying the log."],
      use: ["Stream: fraud detection, real-time dashboards, alerting", "Batch: billing, ML training, reporting"],
      pitfalls: ["Using processing time for business metrics"] },

    /* ---------------------- Distributed Systems --------------------- */
    { id: "consensus", cat: "Distributed Systems", anim: "raft", title: "Consensus: Raft & Paxos",
      summary: "Getting a group of nodes to agree on a value (or an ordered log) despite failures. The foundation of leader election and strongly consistent replication.",
      points: ["Raft: a leader is elected by majority vote per term. The leader appends entries and replicates to followers. An entry is committed once a majority stores it.", "Followers become candidates if they hear no heartbeat within a randomised election timeout. Randomisation avoids split votes.", "Tolerates f failures with 2f + 1 nodes (3 nodes → 1 failure, 5 → 2).", "Used by etcd, Consul, CockroachDB, TiKV, Kafka KRaft, MongoDB (Raft-like). Paxos underpins Chubby and Spanner; ZooKeeper uses ZAB.", "Consensus is expensive (a majority round trip per write), so it's used for metadata, locks and configuration, or per shard."],
      use: ["Leader election, distributed locks, config and service registries", "Replicated state machines for strongly consistent DBs"],
      pitfalls: ["Even-sized clusters (4 nodes tolerate only 1 failure, same as 3)", "Spreading a consensus group across distant regions (latency)"] },
    { id: "leader-election-locks", cat: "Distributed Systems", title: "Leader Election & Distributed Locks",
      summary: "Ensure only one node does something (runs the scheduler, owns a shard) at a time.",
      points: ["Use a consensus-backed store: etcd leases, ZooKeeper ephemeral sequential nodes, Consul sessions.", "Leases: a lock expires unless renewed (heartbeat), so a crashed holder releases it automatically.", "Fencing tokens: every lock grant carries a monotonically increasing number; storage rejects writes with old tokens. This protects against GC-paused 'zombie' leaders.", "Redis SET NX PX works as a best-effort lock (efficiency); Redlock is debated for correctness-critical uses."],
      use: ["Singleton jobs, shard ownership, preventing duplicate work"],
      pitfalls: ["Locks without expiry (deadlock on crash)", "Assuming a lock holder can't be paused past lease expiry"] },
    { id: "unique-ids", cat: "Distributed Systems", anim: "snowflake", title: "Unique ID Generation",
      summary: "Generate unique (often time-sortable) IDs across many machines without a central bottleneck.",
      points: ["Auto-increment: simple but a single-node bottleneck, and it leaks counts.", "UUID v4: 128-bit random, with no coordination. Not sortable, and a poor B-tree index locality.", "UUID v7 / ULID: time-ordered 128-bit, sortable. Good default for DB keys now.", "Snowflake (Twitter): 64-bit = 41-bit ms timestamp + 10-bit machine id + 12-bit sequence → 4,096 IDs/ms per machine, roughly time-sorted.", "Ticket servers / range allocation: a central DB hands out ranges (Flickr, Instagram's Postgres approach)."],
      use: ["Snowflake / UUIDv7 for sharded, sortable primary keys"],
      pitfalls: ["Clock going backwards (NTP), so guard it in Snowflake generators", "Exposing sequential IDs publicly (enumeration)"] },
    { id: "clocks", cat: "Distributed Systems", title: "Time, Clocks & Ordering",
      summary: "Physical clocks drift, so distributed systems use logical clocks to order events.",
      points: ["Wall clocks skew and jump (NTP). Never rely on timestamps across machines for ordering correctness.", "Lamport clocks: a counter incremented on each event, max(local, received)+1 on receive. Gives a total order consistent with causality.", "Vector clocks: one counter per node; can detect concurrent (conflicting) updates. Used in Dynamo/Riak.", "Hybrid logical clocks (HLC): physical time + a logical counter (CockroachDB).", "TrueTime (Spanner): GPS/atomic clocks with bounded uncertainty; commit-wait gives external consistency."],
      use: ["Conflict detection in multi-leader/leaderless systems"],
      pitfalls: ["Last-write-wins based on skewed clocks silently drops data"] },
    { id: "gossip", cat: "Distributed Systems", title: "Gossip Protocols & Failure Detection",
      summary: "Nodes periodically exchange state with random peers, so information spreads epidemically, with no central coordinator.",
      points: ["Each round, a node contacts k random peers and merges membership and heartbeat tables. Converges in O(log N) rounds.", "Failure detection: heartbeats plus timeouts; the phi-accrual detector outputs a suspicion level instead of a binary verdict.", "SWIM: indirect pings through other members reduce false positives.", "Used by Cassandra, Consul (Serf), DynamoDB internals, Redis Cluster."],
      use: ["Cluster membership in large peer-to-peer systems"],
      pitfalls: ["Slow convergence for time-critical decisions (use consensus for those)"] },
    { id: "two-phase-commit", cat: "Distributed Systems", title: "Two-Phase Commit (2PC)",
      summary: "An atomic commit protocol across multiple participants: all commit or all abort.",
      points: ["Phase 1 (prepare): the coordinator asks every participant to prepare. Each writes to its log, locks resources and votes YES or NO.", "Phase 2 (commit/abort): if all voted YES, the coordinator logs COMMIT and tells everyone; otherwise ABORT.", "Blocking problem: if the coordinator crashes after prepare, participants hold locks until it recovers.", "Used inside databases (XA, Spanner with Paxos-replicated participants). Across microservices prefer sagas."],
      use: ["Atomic writes across shards within one database system"],
      pitfalls: ["Using 2PC across independent services: availability and latency suffer"],
      diagram: { nodes: [
        n("c", "Client", "", "client", 100, 260, "Requests a distributed transaction."),
        n("co", "Coordinator", "txn manager", "service", 400, 260, "Drives both phases and logs its decision durably."),
        n("p1", "Participant A", "orders DB", "db", 780, 100, "Votes and holds locks until the decision."),
        n("p2", "Participant B", "payments DB", "db", 780, 260, "Votes and holds locks until the decision."),
        n("p3", "Participant C", "inventory DB", "db", 780, 420, "Votes and holds locks until the decision.")
      ], edges: [["c", "co"], ["co", "p1"], ["co", "p2"], ["co", "p3"]], flows: [{ name: "Commit", steps: [
        ["c", "co", "Commit txn T1"],
        ["co", "p1", "PREPARE T1"], ["co", "p2", "PREPARE T1"], ["co", "p3", "PREPARE T1"],
        ["p1", "co", "YES (logged, locks held)"], ["p2", "co", "YES"], ["p3", "co", "YES"],
        ["co", "p1", "COMMIT (decision logged first)"], ["co", "p2", "COMMIT"], ["co", "p3", "COMMIT"],
        ["co", "c", "Committed. If the coordinator crashed before phase 2, participants would block"]
      ]}]} },
    { id: "saga", cat: "Distributed Systems", anim: "saga", title: "Saga Pattern",
      summary: "A long-lived business transaction split into local transactions, each with a compensating action if a later step fails.",
      points: ["Each step commits locally and publishes an event or reply. On failure, run compensations in reverse (refund payment, release stock, cancel order).", "Orchestration: a central orchestrator (a workflow engine like Temporal or Step Functions) tells each service what to do. Clear flow and easy monitoring.", "Choreography: services react to each other's events. Loose coupling, but the flow is implicit and harder to trace.", "Provides ACD without I: intermediate states are visible, so use semantic locks such as a PENDING status.", "Steps and compensations must be idempotent and retryable."],
      use: ["Checkout, travel booking, onboarding flows across microservices"],
      pitfalls: ["Compensations that can fail with no retry strategy", "Forgetting that other transactions can see intermediate states"] },

    /* -------------------- Reliability & Resilience ------------------ */
    { id: "rate-limiting", cat: "Reliability & Resilience", anim: "rate-limit", title: "Rate Limiting Algorithms",
      summary: "Control request rates per client to protect services from abuse and overload.",
      points: ["Token bucket: tokens refill at rate r up to capacity b; each request takes a token. Allows bursts. (AWS, Stripe)", "Leaky bucket: requests queue and drain at a fixed rate. Smooth output.", "Fixed window counter: count per calendar window. Simple, but allows bursts of 2× at window edges.", "Sliding window log: store timestamps. Exact, but memory-heavy.", "Sliding window counter: interpolates the previous and current windows. Accurate and cheap.", "Implement atomically in Redis (Lua) for distributed enforcement; return 429 + Retry-After."],
      use: ["Public APIs, login endpoints (brute force), expensive operations"],
      pitfalls: ["Non-atomic read-modify-write in distributed limiters"] },
    { id: "circuit-breaker", cat: "Reliability & Resilience", anim: "circuit-breaker", title: "Circuit Breaker",
      summary: "Stop calling a failing dependency for a while, failing fast instead of piling up timeouts. This prevents cascading failures.",
      points: ["Closed: requests flow; failures are counted over a rolling window.", "Open: after the failure threshold, calls fail immediately (or use a fallback) for a cool-down period.", "Half-open: let a few trial requests through. If they succeed, close; if they fail, open again.", "Combine with timeouts, retries (with backoff + jitter), bulkheads and fallbacks (cached or default data).", "Libraries: Resilience4j, Polly, Envoy/Istio outlier detection."],
      use: ["Calls to any remote dependency, especially third parties"],
      pitfalls: ["Retrying aggressively inside an open circuit", "No fallback, so users see errors anyway"] },
    { id: "retries", cat: "Reliability & Resilience", title: "Timeouts, Retries, Backoff & Jitter",
      summary: "Every remote call needs a timeout; retries need backoff and jitter to avoid retry storms.",
      points: ["Always set timeouts (connect + request). The default is often infinite.", "Retry only idempotent operations, or use idempotency keys.", "Exponential backoff: wait base × 2^attempt, with a cap.", "Jitter: randomise the wait (full jitter: random(0, backoff)) to desynchronise clients.", "Retry budgets: cap retries at ~10% of traffic to avoid amplifying an outage. Retry at one layer only, not at every layer.", "Deadline propagation: pass the remaining time budget downstream (gRPC deadlines)."],
      use: ["All network calls"],
      pitfalls: ["Retries at every layer: 3 retries × 4 layers = 81× amplification"] },
    { id: "backpressure", cat: "Reliability & Resilience", title: "Backpressure, Load Shedding & Bulkheads",
      summary: "When demand exceeds capacity, slow producers down or reject work early instead of collapsing.",
      points: ["Backpressure: consumers signal producers to slow down (bounded queues, TCP flow control, reactive streams).", "Load shedding: reject low-priority requests early (503) when overloaded to protect the critical path.", "Bulkheads: isolate resources (thread pools, connection pools, cells) per dependency or tenant so one failure can't sink everything.", "Queue limits: unbounded queues just turn overload into latency and OOM.", "Graceful degradation: turn off non-essential features (recommendations) under load."],
      use: ["Protecting core flows (checkout, login) during spikes"],
      pitfalls: ["Unbounded in-memory queues"] },
    { id: "ha-dr", cat: "Reliability & Resilience", title: "High Availability & Disaster Recovery",
      summary: "Survive failures of instances, zones and regions, and define how much data and time you can lose.",
      points: ["RPO (Recovery Point Objective): the maximum acceptable data loss (time since the last good copy).", "RTO (Recovery Time Objective): the maximum acceptable downtime.", "Strategies, from cheapest and slowest to priciest and fastest: backup & restore → pilot light → warm standby → multi-site active-active.", "Redundancy at every layer: multiple instances across AZs, replicated DBs, multi-region DNS failover.", "Cell-based architecture: split users into independent cells to limit the blast radius.", "Test it: chaos engineering, game days, restore drills."],
      use: ["Tier systems by criticality and assign RPO/RTO per tier"],
      pitfalls: ["Untested backups", "Hidden single points of failure (a shared config service, DNS, auth)"] },
    { id: "health-checks", cat: "Reliability & Resilience", title: "Health Checks, Heartbeats & Failover",
      summary: "Detect failures quickly and route around them automatically.",
      points: ["Liveness: is the process alive? (restart if not). Readiness: can it serve traffic? (remove from the LB if not).", "Shallow checks are cheap; deep checks verify dependencies but can cascade (every instance goes unhealthy when the DB blips).", "Heartbeats + timeouts for cluster membership; tune them to balance fast detection against false positives.", "Active-passive failover (standby takes over) vs active-active (all serve; lose capacity, not availability)."],
      use: ["Kubernetes probes, LB target groups, DB failover managers"],
      pitfalls: ["Deep health checks that take down the whole fleet when a dependency degrades"] },

    /* --------------------- Architecture Patterns -------------------- */
    { id: "microservices", cat: "Architecture Patterns", title: "Monolith vs Microservices",
      summary: "Microservices trade code-level simplicity for independent deployment and scaling, at a big operational cost.",
      points: ["Monolith: one deployable. Simple development, testing and transactions. Can be modular internally.", "Microservices: services own their data and deploy independently. Enable team autonomy and per-service scaling.", "Costs: network calls (latency, failure), distributed data consistency (sagas), observability, versioning, platform overhead.", "Split along business capabilities (bounded contexts, from DDD), not technical layers.", "Strangler fig pattern: incrementally route functionality from the monolith to new services."],
      use: ["Start with a modular monolith; extract services when team or scaling needs demand it"],
      pitfalls: ["A distributed monolith: services that must deploy together or share a database"] },
    { id: "service-discovery", cat: "Architecture Patterns", title: "Service Discovery & Service Mesh",
      summary: "How services find each other's healthy instances in a dynamic environment.",
      points: ["Client-side discovery: the client queries a registry (Consul, Eureka) and load-balances itself.", "Server-side discovery: the client calls an LB or DNS name; the platform routes (Kubernetes Services, AWS ALB).", "Instances register on start and deregister (or expire via TTL) on stop.", "Service mesh (Istio, Linkerd): sidecar proxies handle mTLS, retries, timeouts, circuit breaking, traffic splitting and telemetry, with no app code changes."],
      use: ["Any dynamic microservice deployment"],
      pitfalls: ["Mesh complexity for a handful of services"] },
    { id: "serverless", cat: "Architecture Patterns", title: "Serverless & Event-Driven Compute",
      summary: "Run functions on demand without managing servers, paying per invocation.",
      points: ["FaaS (Lambda, Cloud Functions, Workers): scales to zero and scales out fast. Triggered by HTTP, queues, storage events or cron.", "Pros: no ops, fine-grained cost, elastic.", "Cons: cold starts, execution limits, vendor lock-in, harder local testing, connection-pool issues with relational DBs (use proxies).", "Pairs well with managed services: DynamoDB, S3, SQS, EventBridge."],
      use: ["Spiky or low traffic, glue code, event processing, cron jobs"],
      pitfalls: ["Chatty function-to-function chains", "Unbounded concurrency overwhelming a database"] },
    { id: "multi-region", cat: "Architecture Patterns", title: "Multi-Region Architecture",
      summary: "Serve global users with low latency and survive regional outages.",
      points: ["Active-passive: one region serves; the other is on standby (replicated). Simpler, with RTO in minutes.", "Active-active: all regions serve traffic. Needs a data strategy: partition users by home region, multi-leader with conflict resolution, or globally consistent DBs (Spanner/CockroachDB).", "Route users with GeoDNS/anycast; keep stateless tiers in every region.", "Data residency laws (GDPR) may force regional partitioning."],
      use: ["Global products with strict latency or availability needs"],
      pitfalls: ["Cross-region synchronous calls on the hot path", "Write conflicts in multi-leader setups"] },

    /* ----------------------------- Security ------------------------- */
    { id: "authn-authz", cat: "Security", title: "Authentication & Authorisation",
      summary: "Authentication proves who you are; authorisation decides what you may do.",
      points: ["Sessions: the server stores session state and the client holds an opaque cookie. Easy to revoke; needs a shared session store.", "JWT: a signed, self-contained token. Stateless verification, but hard to revoke, so keep access tokens short-lived and pair them with refresh tokens.", "OAuth 2.0: delegated authorisation (authorization code + PKCE for apps). OpenID Connect adds identity (the ID token) on top.", "Authorisation models: RBAC (roles), ABAC (attributes), ReBAC (relationships, e.g. Google Zanzibar / OpenFGA).", "Service-to-service: mTLS, workload identity, scoped tokens."],
      use: ["Use an identity provider (Auth0, Cognito, Keycloak) rather than rolling your own"],
      pitfalls: ["Long-lived JWTs with no revocation strategy", "Storing tokens in localStorage (XSS risk); prefer httpOnly cookies"],
      diagram: { nodes: [
        n("u", "User", "browser", "client", 80, 260, "The resource owner."),
        n("app", "Client App", "SPA / mobile", "service", 320, 260, "Wants to call the API on the user's behalf."),
        n("as", "Auth Server", "IdP (OIDC)", "edge", 620, 90, "Authenticates the user and issues tokens.", "lock"),
        n("api", "Resource API", "", "service", 620, 430, "Validates the access token on every request.")
      ], edges: [["u", "app"], ["app", "as"], ["u", "as", "", -0.2], ["app", "api"]], flows: [{ name: "OAuth 2.0 auth code + PKCE", steps: [
        ["u", "app", "Click 'Sign in'"],
        ["app", "as", "Redirect: /authorize?client_id&code_challenge&scope=openid profile"],
        ["u", "as", "User logs in (password, MFA, SSO) and consents"],
        ["as", "app", "Redirect back with a one-time authorization code"],
        ["app", "as", "POST /token with code + code_verifier (PKCE)"],
        ["as", "app", "Access token (short-lived), refresh token, ID token"],
        ["app", "api", "Authorization: Bearer <access token>"],
        ["api", "app", "Verify signature + scopes → 200 OK"]
      ]}]} },
    { id: "security-basics", cat: "Security", title: "Security Essentials",
      summary: "The checklist every design should touch on.",
      points: ["Encrypt in transit (TLS everywhere, mTLS internally) and at rest (KMS-managed keys, envelope encryption).", "Secrets in a vault (AWS Secrets Manager, HashiCorp Vault), never in code.", "Least privilege IAM, network segmentation (private subnets, security groups).", "Input validation, parameterised queries (SQL injection), output encoding (XSS), CSRF tokens.", "Rate limiting and WAF for abuse; DDoS protection at the edge.", "Audit logs, PII minimisation, tokenisation (PCI), data retention and deletion (GDPR)."],
      use: ["Mention these briefly in every interview design"],
      pitfalls: ["Security as an afterthought"] },

    /* --------------------------- Observability ---------------------- */
    { id: "observability", cat: "Observability", title: "Logs, Metrics & Traces",
      summary: "The three pillars that let you understand a running system and debug it.",
      points: ["Metrics: cheap numeric time series (RED: Rate, Errors, Duration; USE: Utilisation, Saturation, Errors). Good for dashboards and alerts.", "Logs: detailed discrete events. Structured JSON with request IDs. Expensive at volume, so sample and set retention.", "Distributed tracing: follows one request across services (spans with trace IDs). Finds latency bottlenecks. OpenTelemetry is the standard.", "Correlate all three with a shared trace/request ID.", "Alert on symptoms (SLO burn rate), not causes; keep alerts actionable."],
      use: ["Instrument with OpenTelemetry; Prometheus + Grafana, or Datadog"],
      pitfalls: ["High-cardinality labels in metrics", "Alerting on every CPU spike (pager fatigue)"] },

    /* ---------------------- Algorithms & Structures ----------------- */
    { id: "bloom-filter", cat: "Algorithms & Structures", anim: "bloom", title: "Bloom Filter",
      summary: "A tiny probabilistic set: 'definitely not present' or 'probably present'. No false negatives.",
      points: ["A bit array of m bits and k hash functions. Add: set k bits. Query: if all k bits are set → probably present; if any is 0 → definitely absent.", "False positive rate ≈ (1 − e^(−kn/m))^k. About 10 bits per element gives ~1% FP.", "You can't delete (use a counting Bloom filter or a cuckoo filter).", "Uses: LSM-tree SSTable lookups, crawler URL-seen checks, cache penetration defence, 'username taken?' pre-checks, CDN one-hit-wonder filtering."],
      use: ["Avoid expensive lookups for things that almost certainly don't exist"],
      pitfalls: ["Undersizing, so the FP rate explodes as n grows"] },
    { id: "geospatial", cat: "Algorithms & Structures", anim: "geo", title: "Geospatial Indexing (Geohash, Quadtree, H3)",
      summary: "Index 2-D locations so 'find things near me' is fast.",
      points: ["Geohash: interleave latitude/longitude bits and base32-encode. A shared prefix means nearby. Query the cell + 8 neighbours.", "Quadtree: recursively split space into 4 quadrants until each leaf has ≤ K points. Adapts to density.", "R-tree: bounding-rectangle tree used by PostGIS/GiST; handles shapes, not just points.", "H3 (Uber) hexagons / S2 (Google) cells: hierarchical, with uniform neighbour distances.", "Redis GEO commands (geohash in sorted sets), PostGIS, MongoDB 2dsphere and Elasticsearch geo_point are ready-made."],
      use: ["Ride-hailing, delivery, store locators, dating apps, geofencing"],
      pitfalls: ["Querying only the containing cell (misses neighbours across the boundary)"] },
    { id: "probabilistic", cat: "Algorithms & Structures", title: "HyperLogLog, Count-Min Sketch & Friends",
      summary: "Answer big-data questions approximately with tiny memory.",
      points: ["HyperLogLog: counts distinct elements (unique visitors) with ~0.8% error in 12 KB, regardless of cardinality (Redis PFADD/PFCOUNT).", "Count-Min Sketch: approximate frequency of items (heavy hitters, top-K trending) in fixed memory; may over-count.", "Top-K / heavy hitters: CMS + a min-heap, or the Space-Saving algorithm.", "Reservoir sampling: a uniform random sample from a stream of unknown length.", "MinHash / SimHash: similarity estimation for near-duplicate detection."],
      use: ["Unique counts, trending topics, near-dup detection at scale"],
      pitfalls: ["Using them where exact answers are required (billing)"] },
    { id: "merkle-tree", cat: "Algorithms & Structures", title: "Merkle Trees",
      summary: "A tree of hashes that lets two parties find which parts of large datasets differ, exchanging only O(log n) hashes.",
      points: ["Leaves hash data blocks; parents hash their children. Equal roots mean identical data.", "Compare top-down and descend only into differing subtrees.", "Uses: anti-entropy repair (Cassandra, Dynamo), Git, blockchains, certificate transparency, IPFS, ZFS."],
      use: ["Syncing replicas efficiently"], pitfalls: ["Rebuilding the tree on every write (maintain incrementally)"] },
    { id: "hashing-checksums", cat: "Algorithms & Structures", title: "Hashing, Checksums & Encoding",
      summary: "Common building blocks in designs: content addressing, integrity, compact IDs.",
      points: ["Cryptographic hashes (SHA-256) for content addressing and dedup (Git, Dropbox chunks).", "Non-crypto hashes (MurmurHash, xxHash) for partitioning and hash tables: fast and well distributed.", "Checksums (CRC32) detect corruption in storage and network.", "Base62/Base64 encoding for short, URL-safe IDs.", "Compression: gzip/zstd for logs and payloads; columnar and delta encodings for analytics."],
      use: ["Chunk dedup, partition keys, integrity checks"], pitfalls: ["MD5/SHA-1 for security purposes (broken)"] }
  ];
})();
